snippet::is-deflate-buffer.example:
function isDeflate(buf) {
  if (buf.length < 2 || buf[0] !== 0x78) return false;
  const b = buf[1];
  return b === 1 || b === 0x9c || b === 0xda;
}

snippet::is-directory.example:
import { stat } from 'node:fs/promises'

const isDirectory = async (filepath) => {
  try {
    return (await stat(filepath)).isDirectory()
  } catch (err) {
    if (err.code === 'ENOENT') return false
    throw err
  }
}

snippet::is-electron.example:
function isElectron() {
  return Boolean(
    globalThis.window?.process?.type === "renderer" ||
      globalThis.process?.versions?.electron ||
      globalThis.navigator?.userAgent?.includes("Electron")
  );
}

snippet::is-gzip-buffer.example:
function isGzip(buf) {
  if (buf.length < 3) return false;
  return buf[0] === 31 && buf[1] === 139 && buf[2] === 8;
}

snippet::is-jpg-buffer.example:
function isJpg(buf) {
  if (!buf || buf.length < 3) return false;
  return buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff;
}

